import mongoose from 'mongoose';

export const PAYMENT_METHODS = ['cash', 'gcash', 'card'];
export const DISCOUNT_TYPES = ['none', 'percent', 'fixed'];
export const SALE_STATUSES = ['completed', 'voided'];

const saleSchema = new mongoose.Schema(
  {
    saleNumber: {
      type: String,
      required: true,
      unique: true,
    },
    // Unique key generated by the client for each checkout attempt.
    // A second request with the same key is rejected -> no duplicate sales.
    clientRequestId: {
      type: String,
      required: [true, 'clientRequestId is required'],
      unique: true,
      trim: true,
      minlength: [8, 'clientRequestId is too short'],
      maxlength: [64, 'clientRequestId is too long'],
    },
    customer: {
      type: mongoose.Schema.Types.ObjectId,
      ref: 'Customer',
      default: null,
    },
    // Snapshot so the receipt still shows a name if the customer changes later
    customerName: {
      type: String,
      default: 'Walk-in customer',
    },
    itemCount: {
      type: Number,
      required: true,
      min: [1, 'A sale must contain at least 1 item'],
    },
    subtotal: { type: Number, required: true, min: 0 },
    discountType: {
      type: String,
      enum: { values: DISCOUNT_TYPES, message: '{VALUE} is not a valid discount type' },
      default: 'none',
    },
    discountValue: { type: Number, min: 0, default: 0 },
    discountAmount: { type: Number, min: 0, default: 0 },
    total: { type: Number, required: true, min: 0 },
    vatAmount: { type: Number, min: 0, default: 0 },
    totalCost: { type: Number, min: 0, default: 0 },
    grossProfit: { type: Number, default: 0 },
    paymentMethod: {
      type: String,
      enum: { values: PAYMENT_METHODS, message: '{VALUE} is not a valid payment method' },
      required: [true, 'Payment method is required'],
    },
    amountTendered: { type: Number, min: 0, default: 0 },
    change: { type: Number, min: 0, default: 0 },
    status: {
      type: String,
      enum: { values: SALE_STATUSES, message: '{VALUE} is not a valid status' },
      default: 'completed',
    },
    notes: {
      type: String,
      trim: true,
      maxlength: [200, 'Notes must be at most 200 characters'],
      default: '',
    },
    voidedAt: { type: Date, default: null },
    voidReason: { type: String, trim: true, default: '' },
  },
  { timestamps: true }
);

saleSchema.index({ createdAt: -1 });
saleSchema.index({ status: 1, createdAt: -1 });

export default mongoose.model('Sale', saleSchema);
